  "（恩納村·公寓式附廚房，約 NT$5,000–6,000/晚）；後 2 晚": "（恩納村・キッチン付きアパートメント型、約 NT$5,000–6,000/泊）、後半2泊",
  "OMO5 那霸": "OMO5那覇",
  "（鄰國際通·距機場約 15 分，約 NT$3,000–4,000/晚）。僅 Day 3 退房南下時搬一次行李。": "（国際通り近く・空港まで約15分、約 NT$3,000–4,000/泊）。荷物の移動はDay 3のチェックアウト後に南下する1回だけ。",
  "🧭 動線原則": "🧭 ルートの方針",
  "大致由北而南：Day1–2 待中北部玩萬座毛、美麗海、古宇利；Day3 早上悠閒（BEB5＋恩納道の駅吃午餐）後一路南下、中午拍殘波岬、下午到傍晚玩美國村萬聖節＋夕陽，17:50 離場後到那霸新都心": "おおむね北から南へ：Day1–2は中北部で万座毛、美ら海、古宇利を観光。Day3は朝のんびり（BEB5＋おんなの駅で昼食）してから南下、昼に残波岬で写真、午後から夕方はアメリカンビレッジのハロウィン＋夕日、17:50に出発して那覇新都心で",
  "分兩隊各 90 分": "2班に分かれて各90分",
  "（購物組逛": "（ショッピング班は",
  "、育兒組玩": "へ、子連れ班は",
  "teamLab 未來遊樂園": "チームラボ 未来の遊園地",
  "），在同區會合吃晚餐，約 21:00 入住那霸；Day4 由北往南單向推進（波上宮→糸滿魚市場→豐崎 DMM 水族館→Ashibinaa→瀨長島夕陽），晚上回 OMO5 步行逛國際通；Day5 最後一線往機場。": "へ）、同エリアで合流して夕食、21:00頃に那覇でチェックイン。Day4は北から南へ一方向に進み（波上宮→糸満お魚センター→豊崎のDMMかりゆし水族館→あしびなー→瀬長島の夕日）、夜はOMO5に戻って徒歩で国際通りへ。Day5は最後に空港へ一直線。",
  "🚐 包車配置": "🚐 貸切チャーターの配置",
  "全程包車": "全行程貸切",
  "2 台・每日 10 小時 × 4 天（10/29–11/1）": "2台・1日10時間×4日（10/29–11/1）",
  "Alphard 阿法（日文司機）": "アルファード（日本語ドライバー）",
  "載 4 大 2 小、不放行李；": "は大人4名・子ども2名が乗車、荷物は積まない。",
  "HiAce 海獅（中文司機・大台）": "ハイエース（中国語ドライバー・大型車）",
  "載 5 大 1 小並集中放 9 個大行李箱。3 張嬰兒安全座椅（阿法 2／海獅 1，適合 1–2 歲）。": "は大人5名・子ども1名が乗車し、大型スーツケース9個をまとめて積載。チャイルドシート3台（アルファード2／ハイエース1、1–2歳向け）。",
  "，退房後往機場自理（計程車）。費用 NT$1,650／人／日，全程合計 NT$79,200（訂金已付）。": "、チェックアウト後の空港へは各自（タクシー）。料金 NT$1,650／人／日、全行程合計 NT$79,200（手付金支払済）。",
  "😴 車上補眠": "😴 車内でお昼寝",
  "長車程（Day1 PARCO 北上恩納約 50 分、Day2 古宇利返程 70 分）刻意對齊寶寶午睡時間，讓孩子在有冷氣的汽座上安穩補眠，抵達景點剛好精神飽滿。": "長距離移動（Day1 PARCO→恩納の北上約50分、Day2 古宇利からの帰路70分）はあえて赤ちゃんのお昼寝時間に合わせ、エアコンの効いたチャイルドシートでぐっすり。到着時にはちょうど元気いっぱい。",
  "🍽️ 12 人訂位": "🍽️ 12名の予約",
  "9 大 3 小共 12 人，熱門餐廳座位有限且多需座敷。行前先以電話／官網預約，並備註「3 位幼兒需兒童椅／座敷」。商場美食街選擇多，可現場彈性處理。": "大人9・子ども3の計12名。人気店は席が限られ、座敷が必要なことも多い。事前に電話／公式サイトで予約し、備考に「幼児3名、子ども椅子／座敷希望」と記入。モールのフードコートは選択肢が多く、当日柔軟に対応可。",
  "☔ 雨備": "☔ 雨天プラン",
  "Day 4 的雨備": "Day 4 の雨天プランは",
  "已內建在行程上": "旅程に組み込み済み",
  "：遇雨直接延長「DMM かりゆし水族館＋iias 沖繩豐崎」（同一棟、全室內、育嬰室完備）、砍掉傍晚的瀨長島即可，完全不必移動。若整天大雨想換更大場地，遠端備案是「AEON MALL 沖繩來客夢 Rycom」（巨型室內商場、頂級育嬰室、免費兒童造型推車，距 OMO5 約 25 分）。": "：雨なら「DMMかりゆし水族館＋イーアス沖縄豊崎」（同じ建物・全館屋内・ベビー休憩室完備）での滞在を延長し、夕方の瀬長島をカットするだけで移動不要。終日大雨でより大きな施設に切り替えたい場合の代替案は「イオンモール沖縄ライカム」（巨大屋内モール、充実のベビー休憩室、無料の子ども用カート、OMO5から約25分）。",
