  "停留 30 分": "滞在30分",
  "展望台 8:30–22:00、伴手禮直賣所 9:00–19:00；館內另有學習展示室（9:00–18:00）。入場免費、停車免費。": "展望台 8:30–22:00、お土産直売所 9:00–19:00。館内には学習展示室（9:00–18:00）も。入場無料、駐車無料。",
