  "國家級名勝「萬座毛」——比原版晚 5 分，反而更接近": "国の名勝「万座毛」——元の計画より5分遅いが、かえって",
  "日落（約 17:50）": "日没（約17:50）",
  "的金色光線。造訪國家級名勝「萬座毛」——沿平坦無障礙步道(推車友善)走到斷崖，觀賞招牌的": "の黄金色の光に近づく。国の名勝「万座毛」では、平坦なバリアフリー遊歩道（ベビーカー対応）を断崖まで歩き、名物の",
  "象鼻岩": "象の鼻岩",
  "與東海(東シナ海)無敵海景、吹秋日涼風；腹地內「萬座毛物產中心」可順手採買。": "と東シナ海の絶景を眺めながら秋の涼風を感じる。敷地内の「万座毛 物産センター」でついでに買い物も。",
  "晚上": "夜",
  "約 17:55 抵達「BEB5 沖繩瀨良垣」，": "17:55頃「星野リゾート BEB5沖縄瀬良垣」に到着、",
