  "：Gajumaru Rock（紅芋鬆餅，週四五休）、L LOTA（景觀餐廳，晚餐需預約、週四休）。環島僅 15–20 分；島偏大人旅遊，但海灘＋海洋塔仍適合全家。": "：Gajumaru Rock（紅いもパンケーキ、木金休）、L LOTA（眺望レストラン、夕食は要予約、木曜休）。島一周わずか 15–20 分；大人向けの島だが、ビーチ＋オーシャンタワーは家族全員で楽しめる。",
  "資料參考：加大王的世界（jathao.com）古宇利島遊記；營業時間以店家官方公告為準。": "参考資料：加大王的世界（jathao.com）古宇利島旅行記；営業時間は各店の公式発表を優先。",
  "📌 Day 2 當日小提醒": "📌 Day 2 当日のメモ",
  "本日是全程": "今日は全行程で",
  "拉車最長的一天（約 180 分）": "移動が最も長い日（約180分）",
  "，在 10 小時額度內（餘裕 1 小時 10 分）——這是四天裡第二緊的一天，僅次於 Day 3。": "だが、10時間枠内（余裕 1時間10分）——4日間で Day 3 に次いで2番目にタイトな日。",
  "⚠️ 9:00 出發＋許田停 30 分，美麗海改成 10:40 抵達": "⚠️ 9:00 出発＋許田滞在 30 分のため、美ら海は 10:40 着に変更",
  "（原版 9:00 到）。好處是早上不趕、票也省；代價是": "（元は 9:00 着）。朝は慌てずに済みチケットも安くなるが、代わりに",
  "錯過開館後的空檔，會遇上旅行團時段": "開館直後の空いた時間を逃し、ツアー団体の時間帯にぶつかる",
  "。想避人潮就把許田縮成 15 分快閃（只進去買票），約 10:20 可到。": "。混雑を避けたいなら許田を15分の速攻（チケット購入のみ）にすれば、約 10:20 に着ける。",
  "午餐選 INOH 的話要多留 20 分": "ランチを INOH にするなら20分多めに確保",
  "：行程表抓「本部午餐 40 分」，但 INOH 是吃到飽、現場多為 60 分制，實際會把全日往後推到約": "：行程表では「本部で昼食40分」としているが、INOHは食べ放題で現地は60分制が多く、実際は一日全体が後ろにずれて約",
  "18:10 回 BEB5、包車 9 小時 10 分": "18:10 BEB5帰着・チャーター9時間10分",
  "——仍在 10 小時額度內。好處是": "——それでも10時間枠内。利点は",
  "午餐就在館內 4F，省掉開車找餐廳": "昼食が館内4Fで済み、車でレストランを探す手間が省けること",
  "，而且 12 人達訂位門檻、不用現場排隊。": "、さらに12人で予約条件を満たし、現地で並ばずに済むこと。",
  "記得出發前先打 0980-48-2745 訂位（不收當日）": "出発前に 0980-48-2745 へ電話で予約しておくこと（当日予約不可）",
  "10/27 預報：本日仍是五天裡最濕的一天，而且比 10/22 那版更濕": "10/27 予報：本日は依然として5日間で最も雨が多い日で、しかも10/22版よりさらに雨寄り",
  "——降雨機率從早上 33% 一路爬升，": "——降水確率は朝の33%からじわじわ上昇し、",
  "13:00–16:00 落在 58–73%（15:00 最高 73%，14:00 前後預估約 5mm 陣雨）": "13:00–16:00 は58–73%（15:00 に最高73%、14:00 前後に約5mmのにわか雨の予想）",
  "，其他四天幾乎都在 22% 以下。": "、他の4日はほぼ22%以下。",
  "古宇利島（14:30–16:00）正好卡在這個尖峰": "古宇利島（14:30–16:00）がちょうどこのピークに重なる",
  "，而海灘、心形岩、跨海大橋全是戶外。": "うえ、ビーチ、ハートロック、海に架かる大橋はすべて屋外。",
  "☔ 雨備＝古宇利海洋塔": "☔ 雨天プラン＝古宇利オーシャンタワー",
  "：全室內的 360° 展望台＋貝殼博物館＋無人車，就在島上。晴天把時間留給海灘與心形岩；下雨或風大直接轉進海洋塔，": "：全天候型の360°展望台＋シェルミュージアム＋自動運転カートが島内にある。晴れならビーチとハートロックに時間を使い、雨や強風ならそのままオーシャンタワーへ移動、",
  "不必離開島上、不動包車": "島を離れる必要もなく、チャーターも動かさずに済む",
  "。門票大人 ¥1,000／中小學生 ¥500。": "。入場料 大人¥1,000／小中学生¥500。",
  "依目前預報，這個雨備大概率會用到：請先把票錢與動線跟司機說好，並把雨衣、推車雨罩、寶寶替換衣放在隨手拿得到的地方。": "現在の予報では、この雨天プランを使う可能性が高い：料金と動線をあらかじめドライバーと共有し、レインコート、ベビーカー用レインカバー、赤ちゃんの着替えをすぐ取り出せる場所に置いておくこと。",
  "包車 8:00–16:00＝8 小時，回到 BEB5 即收工": "チャーター 8:00–16:00＝8時間、BEB5到着で終了",
  "（每日額度 10 小時、餘裕 2 小時）。": "（1日の枠10時間、余裕2時間）。",
  "晚餐刻意排在 BEB5 館內／自炊、不用車": "夕食はあえてBEB5館内／自炊にして車を使わない",
  "——恩納餐廳散在 58 號線上走不到，晚上若再出車，當日會變 10.5–12 小時而": "——恩納の飲食店は国道58号沿いに点在し徒歩では行けず、夜にもう一度車を出すと当日10.5–12時間となり",
  "超出額度需加價": "枠を超えて追加料金が発生",
  "。想外食請自行叫計程車。": "。外食したい場合は各自タクシーを手配。",
  "古宇利返程": "古宇利からの帰路は",
  "在名護星巴克拆成 30＋40 兩段": "名護のスターバックスで30＋40の2区間に分割",
  "（總拉車不變），中間下車喝咖啡、看海、讓寶寶透氣；想讓寶寶一路睡滿的話也可以直接跳過這站、照原本 70 分直達。請司機放慢過古宇利大橋讓大人拍照。": "（総移動時間は変わらず）、途中で降りてコーヒーと海を楽しみ、赤ちゃんもひと息；赤ちゃんをずっと寝かせておきたい場合はここを飛ばし、元どおり70分で直行してもよい。古宇利大橋はドライバーにゆっくり走ってもらい、大人は写真撮影を。",
  "水族館與古宇利皆推車友善，園區內有育嬰室、哺乳室，換尿布方便。": "美ら海水族館も古宇利もベビーカーで回りやすく、園内には授乳室・ベビールームがあり、おむつ替えも便利。",
  "順遊備選": "寄り道候補",
  "：北上路線可加名護鳳梨園／OKINAWA 水果樂園／Neo Park（小火車、餵動物），是 1–2 歲最愛的放電點；想更悠閒也可改排 Bios 之丘／東南植物樂園（餵水牛、遊船）。惟本日已滿，需與水族館或古宇利取捨時間。": "：北上ルートにナゴパイナップルパーク／OKINAWAフルーツらんど／ネオパークオキナワ（汽車、動物へのエサやり）を加えることも可能で、1–2歳児が大好きな遊び場。よりのんびり過ごすならビオスの丘／東南植物楽園（水牛へのエサやり、遊覧船）に替えるのも手。ただし本日は予定が詰まっているため、水族館または古宇利の時間と調整が必要。",
