  "本日為全程拉車最長的一天（約 180 分），但水族館與古宇利大橋是沖繩兩大招牌。古宇利返程約 70 分，剛好是三位寶寶在包車上舒適午睡的黃金時間，請司機放慢過橋讓大人拍照。": "本日は全行程で最も移動が長い日（約180分）だが、美ら海水族館と古宇利大橋は沖縄の二大名所。古宇利からの帰路約70分は、ちょうど3人の赤ちゃんがチャーター車内で快適にお昼寝できるゴールデンタイム。橋はドライバーにゆっくり走ってもらい、大人は写真撮影を。",
