  "。新加的兩站都在原本的線上：糸滿魚市場補上全程唯一一餐道地漁港海鮮，DMM 水族館則是順路零繞路的全室內親子館。動線刻意改成": "にアップグレード。新たに加えた2か所はどちらも元のルート上：糸満お魚センターでは全行程で唯一の本場漁港の海鮮を、DMM水族館は寄り道ゼロの全館屋内の子連れ向け施設。動線はあえて",
  "由南往北單向推進": "南から北への一方通行",
  "（波上宮→糸滿→豐崎 DMM→Ashibinaa→瀨長島），不再像原案在豐見城來回折返，並把瀨長島留到黃昏，夕陽＋看飛機一次收；國際通移到晚上從 OMO5 步行前往（18:00 回飯店休整、18:30 入座晚餐 60 分、飯後自由逛街），省下的車程時數全部灌進新景點。": "（波上宮→糸満→豊崎DMM→あしびなー→瀬長島）に変更し、原案のように豊見城を行ったり来たりしない。瀬長島は夕暮れに回し、夕日＋飛行機見物を一度に楽しむ。国際通りは夜にOMO5から徒歩で（18:00ホテルに戻って休憩、18:30夕食着席60分、食後に自由散策）、浮いた車の時間はすべて新スポットに充てた。",
  "Outlet 這段的主目標是一樓的 DESCENTE STORE": "アウトレットの主目的は1FのDESCENTE STORE",
  "——迪桑特集團 9 大品牌直營 outlet，先攻它再逛其他，預逛品牌清單行前另補。包車段 9:00–18:00 共 9 小時，仍在 10 小時額度內；晚餐與逛街全靠步行、不佔車。DMM 與 Day 2 的美麗海不重複（一個室內互動、一個戶外壯觀），而且它讓今天的雨備從「開 25 分去 Rycom」變成「原地多待兩小時」。": "——デサントグループ9ブランドの直営アウトレット。まずここを攻めてからほかを回る。チェックするブランドリストは出発前に追記。チャーター区間は9:00–18:00の計9時間で、10時間枠内。夕食と散策はすべて徒歩で車は使わない。DMMはDay 2の美ら海と重複しない（屋内の体験型と屋外の迫力型）うえ、本日の雨天プランを「25分かけてライカムへ」から「その場で2時間延長」に変えてくれる。",
