  "全日本唯一俯瞰美軍基地的道の駅。4F 展望台正對嘉手納空軍基地跑道，可看 F-15 戰機與空中加油機起降——起降主要在平日，10/29 週四正好。展望台 8:30–22:00、直賣所 9:00–19:00、學習展示室 9:00–18:00；入場與停車免費。": "米軍基地を見下ろせる日本唯一の道の駅。4F展望台は嘉手納基地の滑走路の真正面で、F-15戦闘機や空中給油機の離着陸が見られる——離着陸は主に平日で、10/29（木）はちょうど平日。展望台 8:30–22:00、直売所 9:00–19:00、学習展示室 9:00–18:00。入場・駐車無料。",
