  "🍽 18:30–20:00 · 晚餐 90 分 · 之後約 7 分返回 BEB5": "🍽 18:30–20:00 · 夕食 90分 · その後約7分でBEB5へ戻る",
  "阿古豬涮涮鍋專門店，10/29 18:30・12 位已訂（☎ 098-952-5640）。自家昆布高湯，先下高麗菜絲＋海蘊＋麩，再涮阿古豬，最後煮雜炊收尾；店家主張吃原味、不附柚子醋或芝麻醬。有兒童椅與兒童餐具、寬敞沙發座。": "あぐー豚しゃぶしゃぶ専門店。10/29 18:30・12名で予約済（☎ 098-952-5640）。自家製の昆布だしに、まずキャベツの千切り＋もずく＋麩を入れ、次にアグー豚をしゃぶしゃぶし、最後は雑炊で締める。素材の味で食べるのが店の流儀で、ポン酢やごまだれは付かない。子ども椅・子ども用食器、ゆったりしたソファ席あり。",
  "星野 BEB5 沖繩瀨良垣（旅館）": "星野リゾート BEB5沖縄瀬良垣（ホテル）",
