  "9:35–10:05 · 停留 30 分": "9:35–10:05 · 滞在 30分",
  "國道 58 號上、許田IC 出口 2.5km。美麗海水族館折扣票大人 ¥2,000（窗口與官網 WEB 票皆 ¥2,180，每人省 ¥180），僅收現金；未滿 6 歲免費。營業 8:30–19:00，天婦羅 10:30 才開賣、今天時段吃不到。☎ 0980-54-0880": "国道58号沿い、許田IC出口から2.5km。美ら海水族館の割引券が大人 ¥2,000（窓口・公式WEBチケットはいずれも ¥2,180、1人 ¥180お得）、現金のみ。6歳未満無料。営業 8:30–19:00、天ぷらは10:30販売開始のため今回の時間帯では買えない。☎ 0980-54-0880",
