  "16:30–17:10 · 停留 40 分 · 之後約 40 分返回 BEB5": "16:30–17:10 · 滞在 40分 · その後約40分でBEB5へ戻る",
  "2026/4/15 開幕的海景新店，位在 21 世紀之森公園內、緊鄰 21 世紀之森海灘，走幾十步到沙灘。約 65 坪 71 席、7:30–21:00；琉球赤瓦吧檯牆、榻榻米「緣側」平台，海天一線落地窗。免費出借藺草蓆可到草坪或沙灘野餐，正好讓寶寶下車放電；另有沖繩限定自選水果星冰樂與限定風獅爺。把古宇利→BEB5 的 70 分車程拆成 30＋40，總拉車不變但多一次下車伸展。": "2026/4/15開業の海辺の新店舗。21世紀の森公園内、21世紀の森ビーチに隣接し、数十歩で砂浜へ。約65坪・71席、7:30–21:00。琉球赤瓦のカウンター壁、畳の「縁側」デッキ、海と空が一望できる大きな窓。い草ござの無料貸し出しがあり芝生や砂浜でピクニックができ、赤ちゃんが車を降りて思い切り遊ぶのにちょうどよい。沖縄限定のフルーツを選べるフラペチーノや限定シーサーも。古宇利→BEB5の70分の移動を30＋40に分けることで、総移動時間は変わらず降車休憩が1回増える。",
  "古宇利海洋塔（☔ 雨備）": "古宇利オーシャンタワー（☔ 雨天プラン）",
